    alias UnpaidInvoice := (
        select billing::Invoice filter not .paid
    );

    alias CustomerBalance := billing::Customer {
        outstanding := billing::customer_outstanding(.name)
    };

    alias InvoicePlan := billing::Invoice {
        multi plan := util::installments(.total_due, .installment_count)
    };

}

